#include <bits/stdc++.h>
using namespace std;

bool areEqual(const long long a[], const long long b[]) {
    for (int i = 0; i < 5; i++) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

bool dotProduct(const long long a[], const long long b[]) {
    long long sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += a[i] * b[i];
    }
    return sum > 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalPoints;
    cin >> totalPoints;
    if (totalPoints <= 11) {
        vector<array<long long, 5>> dataPoints(totalPoints);
        for (int i = 0; i < totalPoints; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> dataPoints[i][j];
            }
        }

        vector<vector<array<long long, 5>>> diffVectors(totalPoints, vector<array<long long, 5>>(totalPoints));
        for (int i = 0; i < totalPoints; i++) {
            for (int j = 0; j < totalPoints; j++) {
                for (int k = 0; k < 5; k++) {
                    diffVectors[i][j][k] = dataPoints[j][k] - dataPoints[i][k];
                }
            }
        }

        unordered_set<int> toRemove;

        for (int i = 0; i < totalPoints; i++) {
            bool found = false;
            for (int j = 0; j < totalPoints; j++) {
                for (int k = 0; k < totalPoints; k++) {
                    if (i != j && i != k && !areEqual(diffVectors[i][j].data(), diffVectors[i][k].data()) && dotProduct(diffVectors[i][j].data(), diffVectors[i][k].data())) {
                        toRemove.insert(i + 1);
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
        }

        cout << totalPoints - (int)toRemove.size() << "\n";
        for (int i = 0; i < totalPoints; i++) {
            if (toRemove.find(i + 1) == toRemove.end()) {
                cout << i + 1 << "\n";
            }
        }
    } else {
        cout << 0 << "\n";
    }
    return 0;
}
